import{_ as t,o as a,c as o,a7 as r}from"./chunks/framework.CULO68qY.js";const f=JSON.parse('{"title":"What’s the difference between PMMP, PocketMine and Axolotl-PM?","description":"Differences between PMMP, PocketMine and Axolotl-PM. Axolotl-PM is an actively maintained fork of PMMP.","frontmatter":{"title":"What’s the difference between PMMP, PocketMine and Axolotl-PM?","outline":"deep","description":"Differences between PMMP, PocketMine and Axolotl-PM. Axolotl-PM is an actively maintained fork of PMMP.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/faq/about/pocketmine-vs-pmmp"}]]},"headers":[],"relativePath":"docs/faq/about/pocketmine-vs-pmmp.md","filePath":"docs/faq/about/pocketmine-vs-pmmp.md","lastUpdated":null}'),n={name:"docs/faq/about/pocketmine-vs-pmmp.md"};function i(s,e,l,h,p,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="what-s-the-difference-between-pmmp-and-pocketmine" tabindex="-1">What’s the difference between PMMP and PocketMine? <a class="header-anchor" href="#what-s-the-difference-between-pmmp-and-pocketmine" aria-label="Permalink to &quot;What&#39;s the difference between PMMP and PocketMine?&quot;">​</a></h1><p>In late 2015, <a href="/website/previews/vitepress-native-0137662/docs/faq/about/shoghicp">Shoghi Cervantes</a> was forced to stop developing PocketMine-MP due to conflicts with his job at Mojang. He had exclusive administrator privileges over almost all of the legacy PocketMine infrastructure, including the old <a href="https://github.com/PocketMine" target="_blank" rel="noreferrer">PocketMine GitHub organization</a>, the old <a href="https://forums.pocketmine.net" target="_blank" rel="noreferrer">PocketMine Forums</a>, the old <a href="https://www.pocketmine.net" target="_blank" rel="noreferrer">PocketMine website</a>, and more besides.</p><p>Since he fell out of contact with everyone involved with PocketMine, the remaining team members were unable to maintain infrastructure, properly moderate the forums, or add new GitHub collaborators to maintain the code.</p><p>In September 2016, a collaboration of several members of the old PocketMine team, plus a new developer <a href="https://github.com/dktapps" target="_blank" rel="noreferrer">Dylan (@dktapps)</a>, formed a new organization called PMMP. To work around the inability to work on the old infrastructure, the following things were created:</p><ul><li><a href="https://github.com/pmmp" target="_blank" rel="noreferrer">PMMP GitHub organization</a></li><li><a href="https://forums.pmmp.io" target="_blank" rel="noreferrer">PMMP Forums</a></li><li><a href="https://pmmp.io" target="_blank" rel="noreferrer">PMMP website</a></li></ul><p>and more besides.</p><p>In late 2017, <a href="/website/previews/vitepress-native-0137662/docs/faq/about/shoghicp">Shoghi Cervantes</a> endorsed PMMP as PocketMine’s successor <a href="https://twitter.com/shoghicp/status/931944287780122629" target="_blank" rel="noreferrer">on Twitter</a>, and redirected many parts of the pocketmine.net domain to their corresponding parts of pmmp.io. The old <a href="https://forums.pocketmine.net" target="_blank" rel="noreferrer">PocketMine Forums</a> remains for historical purposes.</p><p><a href="/website/previews/vitepress-native-0137662/docs/faq/about/shoghicp">Shoghi Cervantes</a> also granted the PMMP team access to the <a href="https://github.com/PocketMine" target="_blank" rel="noreferrer">PocketMine GitHub organization</a> at that time, but the team chose not to use it since the <a href="https://github.com/pmmp" target="_blank" rel="noreferrer">PMMP GitHub organization</a> had at that point been established for over a year and had already developed a lot of history of its own, such as issues, which were difficult to migrate at the time, and instead archived all the repositories and added redirections to the new <a href="https://github.com/pmmp" target="_blank" rel="noreferrer">PMMP GitHub organization</a>.</p><h1 id="what-s-the-difference-between-pmmp-and-axolotl-pm" tabindex="-1">What’s the difference between PMMP and Axolotl-PM? <a class="header-anchor" href="#what-s-the-difference-between-pmmp-and-axolotl-pm" aria-label="Permalink to &quot;What&#39;s the difference between PMMP and Axolotl-PM?&quot;">​</a></h1><p>On July 9, 2026, the PMMP team stated that they have no developers left to continue providing updates for newer versions.</p><p>Axolotl-PM is a brand-new fork of PMMP that continues what the original PMMP did, following their legacy.</p>',11)])])}const m=t(n,[["render",i]]);export{f as __pageData,m as default};
